  3	/**
  4	 * This file is part of the Predator-Prey Simulation.
  5	 *
  6	 * An abstract plant organism present in the simulation.
  7	 *
  8	 * @version 2022.03.02
  9	 */
 10	public abstract class Plant extends Organism implements Growable, Consumable {
 11	
 12	    private final PlantTraits traits;
 13	    private double size;
 14	    private final int foodValue;
 15	    private final boolean poisonous;
 16	    private double breedingProbability;
 17	
 18	    /**
 19	     * Constructor for a plant in the simulation.
 20	     *
 21	     * @param traits    Species-level configuration for this plant.
 22	     * @param poisonous Whether the plant is poisonous or not.
 23	     * @param foodValue The food value of this plant when eaten.
 24	     * @param size      The initial size of this plant.
 25	     * @param randomAge Whether the plant should have a random age or not.
 26	     * @param field     The field in which the plant resides.
 27	     * @param location  The location in which the plant spawns into.
 28	     */
 29	    public Plant(PlantTraits traits, boolean poisonous, int foodValue, double size,
 30	                 boolean randomAge, Field field, Location location) {
 31	        super(randomAge, field, location);
 32	        this.traits    = traits;
 33	        this.size      = size;
 34	        this.foodValue = foodValue;
 35	        this.poisonous = poisonous;
 36	        this.breedingProbability = traits.lowBreedingProbability;
 37	    }
 38	
 39	    // ── Organism stat getters (satisfied here so subclasses need not override) ──
 40	
 41	    @Override public int    getMaxAge()        { return traits.maxAge; }
 42	    @Override public int    getBreedingAge()   { return traits.breedingAge; }
 43	    @Override public int    getMaxLitterSize() { return traits.maxLitterSize; }
 44	
 45	    @Override
 46	    public double getBreedingProbability() { return breedingProbability; }
 47	
 48	    // ── Growable interface ─────────────────────────────────────────────────────
 49	
 50	    @Override public double getMaxSize()                   { return traits.maxSize; }
 51	    @Override public double getSize()                      { return size; }
 52	
 53	    @Override
 54	    public void grow() {
 55	        size = size * traits.growthRate > traits.maxSize ? 1 : size * traits.growthRate;
 56	        if (size == 0) remove();
 57	    }
 58	
 59	    // ── Consumable interface ───────────────────────────────────────────────────
 60	
 61	    @Override public int     getFoodValue()  { return foodValue; }
 62	    @Override public boolean isPoisonous()   { return poisonous; }
 63	
 64	    @Override
 65	    public void setEaten() {
 66	        removeFromField();
 67	    }
 68	
 69	    // ── Breeding ───────────────────────────────────────────────────────────────
 70	
 71	    @Override
 72	    protected boolean canBreed() {
 73	        return getAge() >= getBreedingAge();
 74	    }
 75	
 76	    // ── act() — shared across all plant species ────────────────────────────────
 77	
 78	    /**
 79	     * Returns the weather types that boost this plant's breeding probability.
 80	     * Concrete plant classes declare which WeatherTypes trigger the high rate.
 81	     *
 82	     * @return Array of WeatherType values that trigger high breeding probability.
 83	     */
 84	    abstract protected WeatherType[] getBoostWeatherTypes();
 85	
 86	    /**
 87	     * Grows and attempts to spread seeds each step, with a boosted breeding
 88	     * probability whenever any of the boost weather types appear in recent history.
 89	     */
 90	    @Override
 91	    public void act(List<Organism> newPlants, Weather weather, TimeOfDay time) {
 92	        if (isAlive()) {
 93	            breedingProbability = traits.lowBreedingProbability;
 94	            for (WeatherType boostType : getBoostWeatherTypes()) {
 95	                if (weather.getRecentWeather().contains(boostType)) {
 96	                    breedingProbability = traits.highBreedingProbability;
 97	                    break;
 98	                }
 99	            }
100	            grow();
101	            giveBirth(newPlants);
102	        }
103	    }
104	
105	}
