  8	public abstract class Scavenger extends HungryAnimal {
  9	
 10	    /**
 11	     * Constructor for a scavenger in the simulation.
 12	     *
 13	     * @param traits    Species-level configuration for this scavenger.
 14	     * @param foodLevel The initial food level of this scavenger.
 15	     * @param randomAge Whether the scavenger should have a random age or not.
 16	     * @param field     The field in which the scavenger resides.
 17	     * @param location  The location in which the scavenger spawns into.
 18	     */
 19	    public Scavenger(AnimalTraits traits, int foodLevel, boolean randomAge, Field field, Location location) {
 20	        super(traits, foodLevel, randomAge, field, location);
 21	    }
 22	
 23	    /**
 24	     * Searches adjacent cells for a dead Prey corpse to eat.
 25	     *
 26	     * @return The location of the consumed corpse, or null if none found.
 27	     */
 28	    @Override
 29	    public Location findFood() {
 30	        Field field = getField();
 31	        for (Location where : field.adjacentLocations(getLocation())) {
 32	            Organism obj = field.getObjectAt(where);
 33	            if (obj instanceof Prey) {
 34	                Prey prey = (Prey) obj;
 35	                if (!prey.isAlive()) {
 36	                    eat(prey);
 37	                    return where;
 38	                }
 39	            }
 40	        }
 41	        return null;
 42	    }
 43	
 44	    /**
 45	     * Unconditionally eats a dead prey corpse.
 46	     *
 47	     * @param consumable The corpse to be consumed.
 48	     * @return true always (scavengers never leave their food).
 49	     */
 50	    @Override
 51	    public boolean eat(Consumable consumable) {
 52	        consumable.setEaten();
 53	        incrementFoodLevel(consumable.getFoodValue());
 54	        return true;
 55	    }
 56	}

