  1	import java.util.List;
  2	import java.util.Random;
  3	
  4	/**
  5	 * This file is part of the Predator-Prey Simulation.
  6	 *
  7	 * An abstract class representing any organism in the simulation.
  8	 *
  9	 * @version 2022.03.02
 10	 */
 11	public abstract class Organism {
 12	
 13	    // steps a dead body lingers on the field before auto-removal
 14	    private static final int LIFETIME_AFTER_DEATH = 40;
 15	    private boolean alive;
 16	    private boolean removed;
 17	    private Field field;
 18	    private Location location;
 19	    private int howLongDead;
 20	
 21	    private int age;
 22	
 23	    // shared random generator to generate consistent results
 24	    private static final Random rand = Randomizer.getRandom();
 25	
 26	    /**
 27	     * Constructor for an Organism in the simulation.
 28	     *
 29	     * @param randomAge Whether we assign this organism a random age or not.
 30	     * @param field The field in which this organism resides.
 31	     * @param location The location in which this organism is spawned into.
 32	     */
 33	    public Organism(boolean randomAge, Field field, Location location) {
 34	        alive = true;
 35	        this.field = field;
 36	        setLocation(location);
 37	
 38	        age = randomAge ? rand.nextInt(getMaxAge()) : 0;
 39	    }
 40	
 41	    /**
 42	     * Abstract method for what an organism does, i.e. what is always run at every step.
 43	     *
 44	     * @param newOrganisms A list of all newborn organisms in this simulation step.
 45	     * @param weather The current state of weather in the simulation.
 46	     * @param time The current state of time in the simulation.
 47	     */
 48	    abstract public void act(List<Organism> newOrganisms, Weather weather, TimeOfDay time);
 49	
 50	    /**
 51	     * Check whether the organism is alive or not.
 52	     * @return true if the organism is still alive.
 53	     */
 54	    protected boolean isAlive()
 55	    {
 56	        return alive;
 57	    }
 58	
 59	    /**
 60	     * Removes the current organism from the field.
 61	     */
 62	    protected void remove() {
 63	        setDead();
 64	        removeFromField();
 65	        removed = true;
 66	    }
 67	
 68	    /**
 69	     * Return whether the current organism object is supposed
 70	     * to be removed from the simulation.
 71	     *
 72	     * @return A boolean value representing if the organism has been removed or not.
 73	     */
 74	    public boolean isRemoved() {
 75	        return removed;
 76	    }
 77	
 78	    /**
 79	     * Indicate that the organism is no longer alive.
 80	     */
 81	    protected void setDead()
 82	    {
 83	        alive = false;
 84	    }
 85	
 86	    /**
 87	     * Return the organism's location.
 88	     * @return The organism's location.
 89	     */
 90	    protected Location getLocation()
 91	    {
 92	        return this.location;
 93	    }
 94	
 95	    /**
 96	     * Place the organism at the new location in the given field.
 97	     * @param newLocation The organism's new location.
 98	     */
 99	    protected void setLocation(Location newLocation)
100	    {
