 14	    private static final int SATIATION_THRESHOLD = 10;
 15	
 16	    private int foodValue;
 17	    private double activeness;
 18	
 19	    // shared random generator to generate consistent results
 20	    private static final Random rand = Randomizer.getRandom();
 21	
 22	    /**
 23	     * Constructor for a Prey in the simulation.
 24	     *
 25	     * @param traits    Species-level configuration for this prey.
 26	     * @param foodValue The initial food value carried by this prey.
 27	     * @param randomAge Whether we assign this prey a random age or not.
 28	     * @param field     The field in which this prey resides.
 29	     * @param location  The location in which this prey is spawned into.
 30	     */
 31	    public Prey(AnimalTraits traits, int foodValue, boolean randomAge, Field field, Location location) {
 32	        super(traits, randomAge, field, location);
 33	        this.foodValue  = foodValue;
 34	        this.activeness = DEFAULT_ACTIVENESS;
 35	    }
 36	
 37	    /**
 38	     * Returns the activeness multiplier applied during this prey's rest period.
 39	     * Override in each concrete species with the species-specific fraction.
 40	     *
 41	     * @return A double in (0, 1] representing reduced activity.
 42	     */
 43	    abstract protected double getRestActiveness();
 44	
 45	    /**
 46	     * Performs one simulation step: ages, breeds, spreads disease, forages, and moves.
 47	     * Dead prey linger on the field so scavengers can eat their corpses.
 48	     */
 49	    @Override
 50	    public void act(List<Organism> newOrganisms, Weather weather, TimeOfDay time) {
 51	        incrementAge();
 52	        setActiveness(DEFAULT_ACTIVENESS);
 53	
 54	        if (isAlive()) {
 55	            giveBirth(newOrganisms);
 56	
 57	            if (rand.nextDouble() <= getDeathByDiseaseProbability()) {
 58	                remove();
 59	                return;
 60	            }
 61	
 62	            if (time == getRestTime()) {
 63	                setActiveness(getRestActiveness());
 64	            }
 65	
 66	            if (rand.nextDouble() <= getActiveness()) {
 67	                Location newLocation = rand.nextDouble() <= getDiseaseSpreadProbability()
 68	                    ? findAnimalToInfect() : findFood();
 69	
 70	                if (newLocation == null || getFoodValue() > SATIATION_THRESHOLD) {
 71	                    newLocation = getField().freeAdjacentLocation(getLocation());
 72	                }
 73	
 74	                if (newLocation != null) {
 75	                    setLocation(newLocation);
 76	                } else {
 77	                    remove();
 78	                }
 79	            }
 80	        } else {
 81	            decayifDead();
 82	        }
 83	    }
