 91	    public Location findFood() {
 92	        Field field = getField();
 93	        for (Location where : field.adjacentLocations(getLocation())) {
 94	            Organism organism = field.getObjectAt(where);
 95	            if (organism instanceof Plant) {
 96	                Plant plant = (Plant) organism;
 97	                if (plant.isAlive()) {
 98	                    plant.setDead();
 99	                    return eat(plant) ? where : null;
100	                }
101	            }
102	        }
