  2	
  3	/**
  4	 * This file is part of the Predator-Prey Simulation.
  5	 *
  6	 * An abstract animal organism present in the simulation.
  7	 *
  8	 * @version 2022.03.02
  9	 */
 10	public abstract class Animal extends Organism implements AbleToEat {
 11	
 12	    private static final double INFECTION_TRANSMISSION_PROBABILITY = 0.01;
 13	
 14	    private final AnimalTraits traits;
 15	    private final Gender gender;
 16	    private boolean infected;
 17	
 18	    // shared random generator to generate consistent results
 19	    private static final Random rand = Randomizer.getRandom();
 20	
 21	    /**
 22	     * Constructor for an animal in the simulation.
 23	     *
 24	     * @param traits    Species-level configuration for this animal.
 25	     * @param randomAge Whether the animal should have a random age or not.
 26	     * @param field     The field in which the animal resides.
 27	     * @param location  The location in which the animal spawns into.
 28	     */
 29	    public Animal(AnimalTraits traits, boolean randomAge, Field field, Location location) {
 30	        super(randomAge, field, location);
 31	        this.traits = traits;
 32	        this.gender = Gender.getRandom();
 33	        this.infected = false;
 34	    }
 35	
 36	    // ── Organism stat getters (satisfied here so subclasses need not override) ──
 37	
 38	    @Override public double getBreedingProbability()       { return traits.breedingProbability; }
 39	    @Override public int    getMaxLitterSize()             { return traits.maxLitterSize; }
 40	    @Override public int    getMaxAge()                    { return traits.maxAge; }
 41	    @Override public int    getBreedingAge()               { return traits.breedingAge; }
 42	
 43	    // ── Disease stat getters ───────────────────────────────────────────────────
 44	
 45	    protected double getDiseaseSpreadProbability()         { return traits.diseaseSpreadProbability; }
 46	    protected double getDeathByDiseaseProbability()        { return traits.deathByDiseaseProbability; }
 47	
 48	    // ── Rest behaviour (common to Predator, Scavenger, and Prey) ──────────────
 49	
 50	    /**
 51	     * Returns the time of day at which this animal is inactive.
 52	     * Provided by traits so concrete subclasses need not override it.
 53	     */
 54	    protected TimeOfDay getRestTime()                      { return traits.restTime; }
 55	
 56	    // ── Breeding ───────────────────────────────────────────────────────────────
 57	
 58	    /**
 59	     * Checks adjacent locations for an animal of the same species and
 60	     * opposite gender.
 61	     *
 62	     * @return Whether this animal can breed or not.
 63	     */
 64	    @Override
 65	    protected boolean canBreed() {
 66	        if (getAge() < getBreedingAge()) return false;
 67	        for (Location loc : getField().adjacentLocations(getLocation())) {
 68	            Organism obj = getField().getObjectAt(loc);
 69	            if (obj != null && obj.getClass() == getClass()) {
 70	                Animal other = (Animal) obj;
 71	                if (isMale() != other.isMale()) return true;
 72	            }
 73	        }
 74	        return false;
 75	    }
 76	
 77	    // ── Gender ─────────────────────────────────────────────────────────────────
 78	
 79	    protected boolean isMale() { return gender == Gender.MALE; }
 80	
 81	    // ── Disease ────────────────────────────────────────────────────────────────
 82	
 83	    protected boolean isInfected() { return infected; }
 84	
 85	    protected void infect(Animal animal) { animal.infected = true; }
 86	
 87	    /**
 88	     * If this animal is infected, attempts to infect a healthy animal in
 89	     * an adjacent cell.
 90	     *
 91	     * @return The location of the targeted neighbour, or null if none found.
 92	     */
 93	    protected Location findAnimalToInfect() {
 94	        if (!infected) return null;
 95	        for (Location loc : getField().adjacentLocations(getLocation())) {
 96	            Organism organism = getField().getObjectAt(loc);
 97	            if (organism instanceof Animal) {
 98	                Animal animal = (Animal) organism;
 99	                if (animal.isAlive() && !animal.isInfected()) {
100	                    if (rand.nextDouble() <= INFECTION_TRANSMISSION_PROBABILITY) {
101	                        infect(animal);
102	                    }
103	                    return loc;
104	                }
105	            }
106	        }
107	        return null;
108	    }
109	}

